<div class="revision-card">
<h2>Vijayanagara Empire</h2>

<h3>Genesis &amp; Founding (1336‑1380)</h3>
<ul>
<li><strong>Founders:</strong> The brothers <strong>Harihara I</strong> and <strong>Bukka Raya I</strong> of the Sangama dynasty, formerly in the service of the <a href="https://en.wikipedia.org/wiki/Kakatiya_Dynasty" target="_blank">Kakatiyas</a> and later of the <a href="https://en.wikipedia.org/wiki/Delhi_Sultanate" target="_blank">Delhi Sultanate</a>.</li>
<li><strong>Motivation:</strong> Reaction to repeated invasions by the Sultanate of Delhi and the need for a Hindu political centre in the Deccan.</li>
<li><strong>Etymology:</strong> “Vijayanagara” literally means “City of Victory”, chosen after the decisive victory over the Sultanate at the battle of <strong>Saluva</strong> (c. 1336).</li>
<li><strong>Capital:</strong> Initially the modest town of <a href="https://en.wikipedia.org/wiki/Hampi" target="_blank"><strong>Hampi</strong></a>, later officially renamed Vijayanagara.</li>
<li><strong>Early legitimacy:</strong> Gained the tacit blessing of the <a href="https://en.wikipedia.org/wiki/Islamic_Sultanate_of_Bahmani" target="_blank">Bahmani Sultanate</a> in exchange for tribute, which was later repudiated as the empire grew.</li>
</ul>

<h3>Dynastic Chronology</h3>
<table>
<thead>
<tr><th>Dynasty</th><th>Period</th><th>Key Features</th></tr>
</thead>
<tbody>
<tr><td>Sangama</td><td>1336‑1485</td><td>Consolidated core territories, expanded into the Southern Peninsula, and built the first urban infrastructure.</td></tr>
<tr><td>Saluva</td><td>1485‑1505</td><td>Marked by internal strife; <a href="https://en.wikipedia.org/wiki/Saluva_Gopala_Raya" target="_blank"><strong>Saluva Narasimha Deva Raya</strong></a> restored stability.</td></tr>
<tr><td>Tuluva</td><td>1505‑1570</td><td>Golden age under <a href="https://en.wikipedia.org/wiki/Krishna_Deva_Raya" target="_blank"><strong>Krishna Deva Raya</strong></a>, his son <strong>Achyuta Deva Raya</strong>, and successors.</td></tr>
<tr><td>Aravidu</td><td>1570‑1646</td><td>Last dynasty; territorial retreat and eventual fall after the Battle of Talikota.</td></tr>
</tbody>
</table>

<h3>Administrative Structure</h3>
<ul>
<li><strong>Central Administration</strong>
<ul>
<li><strong>Emperor (Raja):</strong> Supreme military and religious authority; titles varied – <em>Mahaprabhu</em>, <em>Chakravarti</em>.</li>
<li><strong>Prime Minister (Mahamantri) &amp; Council of Ministers:</strong> Managed finance, foreign affairs, and civil law.</li>
<li><strong>Imperial Secretaries (Vidyadhar):</strong> Oversaw documentation, land grants, and revenue inscriptions.</li>
</ul>
</li>
<li><strong>Provincial Governance</strong>
<ul>
<li><strong>Nayankara System:</strong> Land revenue tied to military service – a <em>nayaka</em> (feudatory) retained a share of the produce after providing troops.</li>
<li><strong>Mandala Model:</strong> Peripheral provinces enjoyed semi‑autonomy, ensuring loyalty through marriage alliances and religious patronage.</li>
<li><strong>Revenue Officials:</strong> <strong>Deshmukhs</strong> and <strong>Patils</strong> collected land taxes and maintained local order.</li>
</ul>
</li>
</ul>

<h3>Military Apparatus</h3>
<ul>
<li><strong>Composition:</strong> A mixed force of infantry, cavalry, and a powerful war‑elephant corps.</li>
<li><strong>Weaponry:</strong> Match‑lock muskets (introduced by the Portuguese), composite bows, and sophisticated siege artillery.</li>
<li><strong>Strategic Doctrine:</strong> Defensive tactics on the Deccan plateau combined with offensive campaigns into the peninsular coasts.</li>
<li><strong>Notable Battles:</strong> Victory at the <a href="https://en.wikipedia.org/wiki/Battle_of_Talikota" target="_blank"><strong>Battle of Talikota (1565)</strong></a> (catastrophic defeat), earlier triumphs against the <a href="https://en.wikipedia.org/wiki/Bahmani_Sultanate" target="_blank"><strong>Bahmani Sultanate</strong></a> and the <a href="https://en.wikipedia.org/wiki/Gajapati_Kingdom" target="_blank"><strong>Gajapati Kingdom</strong></a>.</li>
</ul>

<h3>Economic Foundations</h3>
<ul>
<li><strong>Agriculture:</strong> Extensive irrigation through tanks and canals; main crops – rice, millets, cotton, sugarcane.</li>
<li><strong>Trade Networks</strong>
<ul>
<li><strong>Domestic:</strong> Coastal ports such as <strong>Bombay (Beypore)</strong> and <strong>Chennai (Madras)</strong> facilitated intra‑peninsular exchange.</li>
<li><strong>Overseas:</strong> Direct maritime links with <a href="https://en.wikipedia.org/wiki/Portuguese_Empire" target="_blank"><strong>Portugal</strong></a>, the <a href="https://en.wikipedia.org/wiki/Dutch_East_India_Company" target="_blank"><strong>Dutch East India Company</strong></a>, and <a href="https://en.wikipedia.org/wiki/Arabian_Peninsula" target="_blank"><strong>Arab</strong></a> merchants for spices, textiles, and precious stones.</li>
</ul>
</li>
<li><strong>Taxation:</strong> Dual system – land revenue (Varaha, Sali) and market taxes on commodities such as pepper, sandalwood, and precious metals.</li>
<li><strong>Currency:</strong> Gold and silver <strong>Pagodas</strong> and copper <strong>Fanams</strong> minted under imperial standards.</li>
</ul>

<h3>Socio‑Cultural Milieu</h3>
<ul>
<li><strong>Religious Landscape</strong>
<ul>
<li>State patronage of <a href="https://en.wikipedia.org/wiki/Hinduism" target="_blank"><strong>Hinduism</strong></a>, especially the Vaishnavite tradition; construction of numerous Venkateswara and Ranganathaswamy temples.</li>
<li>Tolerance of <a href="https://en.wikipedia.org/wiki/Jainism" target="_blank"><strong>Jainism</strong></a> and <a href="https://en.wikipedia.org/wiki/Islam" target="_blank"><strong>Islam</strong></a>; Muslim artisans employed for architecture and administration.</li>
<li>Royal patronage of the Bhakti movement, fostering a syncretic literary culture.</li>
</ul>
</li>
<li><strong>Language &amp; Literature</strong>
<ul>
<li>Official court language: <strong>Kannada</strong> (early period) later supplanted by <strong>Telugu</strong> and <strong>Sanskrit</strong> for religious and literary works.</li>
<li>Prominent poets: <a href="https://en.wikipedia.org/wiki/Turrebul_Takkala" target="_blank"><strong>Allasani Peddana</strong></a>, <a href="https://en.wikipedia.org/wiki/Ramanuja" target="_blank"><strong>Ramanuja</strong></a> (philosophical influence), and <a href="https://en.wikipedia.org/wiki/Pedda_Balija_Rao" target="_blank"><strong>Pedda Tirumala</strong></a>.</li>
<li>Creation of the celebrated epic <strong>“Amuktam Maṭṭu”</strong> by Krishnadevaraya.</li>
</ul>
</li>
<li><strong>Art &amp; Architecture</strong>
<ul>
<li>Distinctive Vijayanagara style – fusion of Chalukyan, Hoysala, and Pandya elements.</li>
<li>Monumental complexes at <a href="https://en.wikipedia.org/wiki/Hampi" target="_blank"><strong>Hampi</strong></a>: <strong>Virupaksha Temple</strong>, <strong>Vittala Temple</strong> with its iconic stone chariot, and the massive <strong>Lotus Mahal</strong>.</li>
<li>Secular architecture: massive market squares (Mahanavami Dibba), royal audience halls, and elaborate water reservoirs such as <strong>Khadri</strong>.</li>
</ul>
</li>
<li><strong>Caste &amp; Social Order</strong>: While the empire upheld the traditional varna‑jati framework, the Nayankara system allowed upward mobility for warriors and administrators, blurring rigid hierarchies.</li>
</ul>

<h3>Foreign Relations &amp; Diplomacy</h3>
<ul>
<li><strong>Western Powers:</strong> Early cordial ties with the <a href="https://en.wikipedia.org/wiki/Portuguese_Empire" target="_blank"><strong>Portuguese Estado da India</strong></a>, granting commercial concessions at ports like <strong>Karwar</strong> and <strong>Bangalore</strong>.</li>
<li><strong>Regional Sultanates:</strong> Periodic wars and alliances with the <a href="https://en.wikipedia.org/wiki/Bahmani_Sultanate" target="_blank"><strong>Bahmani</strong></a> and its successor states (<strong>Bijapur</strong>, <strong>Golconda</strong>).</li>
<li><strong>Maratha Interaction:</strong> In the later Aravidu phase, emergent Maratha chiefs received land grants, sowing seeds for future geopolitical shifts.</li>
<li><strong>Treaties:</strong> Post‑Talikota settlements led to a temporary truce with the Deccan Sultanates, though the empire never fully recovered its former dominance.</li>
</ul>

<h3>Decline &amp; Fall (1565‑1646)</h3>
<ul>
<li><strong>Battle of Talikota (1565):</strong> Coalition of Deccan Sultanates (Bijapur, Golconda, Ahmadnagar, and Bidar) decisively defeated Vijayanagara forces, leading to the sack of the capital.</li>
<li><strong>Sack of Hampi:</strong> Systematic looting, temple destruction, and mass displacement; the city's population fled to peripheral forts.</li>
<li><strong>Fragmentation:</strong> Remaining Aravidu rulers retained control over reduced territories (e.g., <strong>Mysore</strong>, <strong>Tiruchirappalli</strong>, <strong>Kolar</strong>) but lacked central authority.</li>
<li><strong>Long‑Term Impact:</strong> The empire’s legacy persisted in the diffusion of its administrative practices to successor states, especially the <a href="https://en.wikipedia.org/wiki/Kingdom_of_Mysore" target="_blank"><strong>Kingdom of Mysore</strong></a>, and its cultural imprint endures in South Indian art, literature, and temple architecture.</li>
</ul>

<h3>Historical Significance &amp; Legacy</h3>
<p><strong>Vijayanagara</strong> represented the last formidable indigenous Hindu polity that successfully resisted the expansionist ambitions of the northern Sultanates, providing a political and cultural sanctuary for the South. Its administrative innovations such as the <strong>nayankara</strong> system foreshadowed later feudal arrangements, while its artistic synthesis created a distinctive architectural idiom that continues to attract scholars and tourists alike. Understanding the empire’s rise, zenith, and abrupt collapse offers critical insights into the dynamics of pre‑colonial Indian statecraft, inter‑regional trade, and the interplay of religion and politics in shaping South Asian civilization.</p>
</div>
