      <tr style="background:#1e1e2a;">
        <td style="padding:8px;border:1px solid #444;"><strong>Core Goal</strong></td>
        <td style="padding:8px;border:1px solid #444;">Kevala jñāna (liberation of the soul)</td>
        <td style="padding:8px;border:1px solid #444;">Nirvāṇa (cessation of suffering)</td>
      </tr>
      <tr>
        <td style="padding:8px;border:1px solid #444;"><strong>View of Self</strong></td>
